<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { Activity,CheckCircle2,CirclePlus,Clock3,Gauge,Pencil,Play,RefreshCw,Trash2,TriangleAlert,X } from '@lucide/vue'
import { createAdminChannelMonitor,deleteAdminChannelMonitor,getAdminChannelMonitorHistory,listAdminChannelMonitors,runAdminChannelMonitor,updateAdminChannelMonitor } from '@/api/admin/channel-monitors'
import type { AdminChannelMonitor,AdminMonitorHistoryItem,AdminMonitorProvider } from '@/api/admin/types'
import ProviderIcon from '@/components/ProviderIcon.vue'
import { formatDateTime } from '@/lib/format'
import { toast } from '@/stores/toast'

const items=ref<AdminChannelMonitor[]>([]);const total=ref(0);const loading=ref(true);const refreshing=ref(false);const pending=ref('');const editorError=ref('');const loadError=ref('');const search=ref('');const provider=ref('');const editorOpen=ref(false);const editing=ref<AdminChannelMonitor|null>(null);const selected=ref<AdminChannelMonitor|null>(null);const history=ref<AdminMonitorHistoryItem[]>([]);const form=reactive({name:'',provider:'anthropic' as AdminMonitorProvider,endpoint:'',apiKey:'',model:'',groupName:'',interval:300,enabled:true});const healthy=computed(()=>items.value.filter(i=>i.primary_status==='operational').length);const attention=computed(()=>items.value.length-healthy.value);const availability=computed(()=>items.value.length?items.value.reduce((s,i)=>s+i.availability_7d,0)/items.value.length:0)
async function load(background=false){if(background)refreshing.value=true;else loading.value=true;loadError.value='';try{const res=await listAdminChannelMonitors({page:1,page_size:20,search:search.value.trim()||undefined,provider:provider.value||undefined});items.value=res.items;total.value=res.total}catch(caught){loadError.value=caught instanceof Error&&caught.message?caught.message:'渠道监控加载失败'}finally{loading.value=false;refreshing.value=false}}
function resetEditor(){form.name=editing.value?.name??'';form.provider=editing.value?.provider??'anthropic';form.endpoint=editing.value?.endpoint??'';form.apiKey='';form.model=editing.value?.primary_model??'';form.groupName=editing.value?.group_name??'';form.interval=editing.value?.interval_seconds??300;form.enabled=editing.value?.enabled??true;editorError.value=''}watch(editorOpen,open=>{if(open)resetEditor()});function openCreate(){editing.value=null;editorOpen.value=true}function openEdit(item:AdminChannelMonitor){editing.value=item;editorOpen.value=true}
async function save(){editorError.value='';if(!form.name.trim()||!form.endpoint.trim()||!form.model.trim()||(!editing.value&&!form.apiKey.trim())){editorError.value='请完整填写名称、端点、API Key 和主模型';return}pending.value='save';try{const payload={name:form.name.trim(),provider:form.provider,endpoint:form.endpoint.trim(),api_key:form.apiKey.trim(),primary_model:form.model.trim(),group_name:form.groupName.trim(),interval_seconds:Math.max(60,Number(form.interval)||300),enabled:form.enabled};const saved=editing.value?await updateAdminChannelMonitor(editing.value.id,payload):await createAdminChannelMonitor(payload);const index=items.value.findIndex(i=>i.id===saved.id);if(index>=0)items.value[index]=saved;else items.value.unshift(saved);editorOpen.value=false;toast.success('监控配置已保存')}catch(caught){editorError.value=caught instanceof Error&&caught.message?caught.message:'保存失败'}finally{pending.value=''}}
async function run(item:AdminChannelMonitor){pending.value=`run-${item.id}`;selected.value=item;try{const res=await runAdminChannelMonitor(item.id);history.value=res.results;toast.success('检测已完成')}catch(caught){toast.error('检测失败',{detail:caught instanceof Error?caught.message:undefined})}finally{pending.value=''}}async function openHistory(item:AdminChannelMonitor){selected.value=item;history.value=[];try{history.value=(await getAdminChannelMonitorHistory(item.id,{limit:50})).items}catch{toast.error('检测历史加载失败')}}async function toggle(item:AdminChannelMonitor){pending.value=`toggle-${item.id}`;try{const updated=await updateAdminChannelMonitor(item.id,{enabled:!item.enabled});items.value=items.value.map(i=>i.id===updated.id?updated:i);toast.success(updated.enabled?'监控已启用':'监控已停用')}catch(caught){toast.error('状态更新失败',{detail:caught instanceof Error?caught.message:undefined})}finally{pending.value=''}}async function remove(item:AdminChannelMonitor){if(!window.confirm(`确认删除监控“${item.name}”？`))return;pending.value=`delete-${item.id}`;try{await deleteAdminChannelMonitor(item.id);items.value=items.value.filter(i=>i.id!==item.id);total.value=Math.max(0,total.value-1);toast.success('监控已删除')}catch(caught){toast.error('删除失败',{detail:caught instanceof Error?caught.message:undefined})}finally{pending.value=''}}
function statusLabel(s:string){return s==='operational'?'正常':s==='degraded'?'偏慢':s==='failed'?'异常':s==='error'?'失败':'待检测'}function latency(v:number|null){return v==null?'—':`${v}ms`}onMounted(()=>void load())
</script>
<template><div class="monitor-page"><header class="page-header drag-region"><div><span>CHANNEL OBSERVABILITY</span><h1>渠道监控</h1><p>维护主动检测任务并观察上游模型可用性。</p></div><button class="primary no-drag" data-testid="create-monitor" @click="openCreate"><CirclePlus :size="17" />新增监控</button></header>
<section class="summary"><div :class="{attention:attention>0}"><CheckCircle2 v-if="attention===0" :size="19"/><TriangleAlert v-else :size="19"/><span>{{ attention===0?'所有监控运行正常':`${attention} 个监控需要关注` }}</span></div><div><Activity :size="17"/><span>启用 {{ items.filter(i=>i.enabled).length }} / {{ total }}</span></div><div><Gauge :size="17"/><span>7 天平均 {{ availability.toFixed(2) }}%</span></div></section>
<form class="filters" @submit.prevent="load(true)"><label><Activity :size="15"/><input v-model="search" placeholder="搜索监控名称" /></label><select v-model="provider"><option value="">全部平台</option><option value="anthropic">Anthropic</option><option value="openai">OpenAI</option><option value="gemini">Gemini</option><option value="grok">Grok</option></select><button type="submit">筛选</button><button class="refresh" type="button" @click="load(true)"><RefreshCw :size="16" :class="{spinning:refreshing}"/></button></form>
<section v-if="loading" class="grid loading"><i v-for="n in 4" :key="n"/></section><section v-else-if="loadError" class="empty page-empty" data-testid="monitor-error"><div><strong>渠道监控加载失败</strong><span>{{ loadError }}</span><button type="button" data-testid="retry-monitors" @click="load()">重新加载</button></div></section><section v-else-if="!items.length" class="empty page-empty" data-testid="monitor-empty"><div><strong>暂无渠道监控</strong><span>新建监控后，可持续观察上游模型可用性。</span><button type="button" @click="openCreate">新增监控</button></div></section><section v-else class="grid"><article v-for="item in items" :key="item.id" class="card" :class="`status-${item.primary_status||'pending'}`"><header><div class="identity"><span><ProviderIcon :provider="item.provider" :size="22"/></span><div><strong>{{ item.name }}</strong><small>{{ item.group_name||'未分组' }} · {{ item.primary_model }}</small></div></div><button class="enabled" :aria-pressed="item.enabled" @click="toggle(item)"><i/></button></header><div class="health"><div><span>当前状态</span><strong>{{ statusLabel(item.primary_status) }}</strong></div><div><span>最近延迟</span><strong>{{ latency(item.primary_latency_ms) }}</strong></div><div><span>7 天可用率</span><strong>{{ item.availability_7d.toFixed(2) }}%</strong></div></div><div class="availability"><i><b :style="{width:`${item.availability_7d}%`}"/></i></div><footer><span><Clock3 :size="13"/>{{ formatDateTime(item.last_checked_at) }}</span><div><button title="检测历史" @click="openHistory(item)"><Activity :size="15"/></button><button :data-testid="`run-monitor-${item.id}`" title="立即检测" @click="run(item)"><Play :size="15"/></button><button title="编辑" @click="openEdit(item)"><Pencil :size="15"/></button><button title="删除" :data-testid="`delete-monitor-${item.id}`" :disabled="pending===`delete-${item.id}`" @click="remove(item)"><Trash2 :size="15"/></button></div></footer></article></section>
<Transition name="fade"><div v-if="editorOpen" class="backdrop" @mousedown.self="editorOpen=false"><section class="editor"><header><div><h2>{{ editing?'编辑监控':'新增监控' }}</h2><p>配置上游健康检测</p></div><button @click="editorOpen=false"><X :size="18"/></button></header><form data-testid="monitor-editor" @submit.prevent="save"><label><span>名称</span><input v-model="form.name" data-testid="monitor-name"/></label><label><span>平台</span><select v-model="form.provider"><option value="anthropic">Anthropic</option><option value="openai">OpenAI</option><option value="gemini">Gemini</option><option value="grok">Grok</option></select></label><label class="wide"><span>检测端点</span><input v-model="form.endpoint" data-testid="monitor-endpoint"/></label><label class="wide"><span>{{ editing?'API Key（留空不修改）':'API Key' }}</span><input v-model="form.apiKey" data-testid="monitor-api-key" type="password"/></label><label><span>主模型</span><input v-model="form.model" data-testid="monitor-model"/></label><label><span>分组标签</span><input v-model="form.groupName"/></label><label><span>检测间隔（秒）</span><input v-model.number="form.interval" type="number" min="60"/></label><label class="checkbox"><input v-model="form.enabled" type="checkbox"/><span>启用监控</span></label><footer class="wide"><button type="button" @click="editorOpen=false">取消</button><button class="save" type="submit">保存</button></footer></form></section></div></Transition>
<Transition name="drawer"><div v-if="selected" class="drawer-backdrop" @mousedown.self="selected=null"><aside data-testid="monitor-history"><header><div><h2>{{ selected.name }}</h2><p>最近检测历史</p></div><button @click="selected=null"><X :size="18"/></button></header><div v-if="!history.length" class="empty">暂无检测结果</div><div v-for="row in history" :key="`${row.id}-${row.checked_at}`" class="history-row"><i :class="row.status"/><div><strong>{{ row.model }}</strong><span>{{ row.message }}</span></div><strong>{{ latency(row.latency_ms) }}</strong><span>{{ formatDateTime(row.checked_at) }}</span></div></aside></div></Transition>
</div></template>
<style scoped>
.monitor-page{width:100%;min-height:100%;padding:28px 30px 34px;overflow:auto}.page-header{display:flex;align-items:flex-end;justify-content:space-between}.page-header>div>span{display:block;margin-bottom:5px;color:var(--accent);font-size:11px;font-weight:720;letter-spacing:.08em}.page-header h1{margin:0;font-size:25px}.page-header p{margin:7px 0 0;color:var(--text-secondary);font-size:14px}.primary,.filters>button{display:flex;height:36px;align-items:center;gap:7px;padding:0 13px;border:0;border-radius:7px;background:var(--accent);color:white}.summary{display:grid;grid-template-columns:1.6fr 1fr 1fr;margin-top:20px;overflow:hidden;background:white;border:1px solid var(--border-subtle);border-radius:8px}.summary>div{display:flex;min-height:58px;align-items:center;gap:9px;padding:0 17px;border-right:1px solid var(--border-subtle);color:#27805a}.summary>div:last-child{border-right:0}.summary>div.attention{color:#aa4c3d}.summary span{color:var(--text-secondary);font-size:12px}.filters{display:flex;gap:8px;margin-top:13px}.filters label{display:flex;min-width:240px;height:37px;align-items:center;gap:7px;padding:0 10px;background:white;border:1px solid var(--border-subtle);border-radius:7px;color:var(--text-tertiary)}.filters input,.filters select{border:0;outline:0;font:inherit}.filters select,.filters>select{height:37px;padding:0 9px;border:1px solid var(--border-subtle);border-radius:7px;background:white}.filters .refresh{width:37px;padding:0;justify-content:center;background:white;border:1px solid var(--border-subtle);color:var(--text-secondary)}.message{padding:8px 11px;background:#edf5ff;border:1px solid #d3e3f8;border-radius:7px;color:#3f67a2;font-size:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:14px}.card{padding:17px;background:rgba(255,255,255,.8);border:1px solid var(--border-subtle);border-radius:8px;box-shadow:0 6px 18px rgba(31,51,78,.04);animation:enter 420ms var(--motion-ease-out) both}.card.status-failed,.card.status-error{border-color:#edc7c0}.card>header{display:flex;align-items:center;justify-content:space-between}.identity{display:flex;min-width:0;align-items:center;gap:9px}.identity>span{display:grid;width:38px;height:38px;background:var(--bg-base);border-radius:8px;place-items:center}.identity>div{display:grid;min-width:0;gap:4px}.identity strong,.identity small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.identity small{color:var(--text-tertiary);font-size:10px}.enabled{position:relative;width:34px;height:20px;border:0;border-radius:12px;background:#d9dfe7}.enabled i{position:absolute;top:3px;left:3px;width:14px;height:14px;background:white;border-radius:50%;transition:transform .16s}.enabled[aria-pressed=true]{background:#3d76d7}.enabled[aria-pressed=true] i{transform:translateX(14px)}.health{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:16px}.health>div{display:grid;gap:4px;padding:9px;background:var(--bg-base);border-radius:6px}.health span{color:var(--text-tertiary);font-size:9px}.health strong{font-family:var(--font-data);font-size:12px}.availability{margin-top:11px}.availability i{display:block;height:5px;background:#edf1f5;border-radius:5px}.availability b{display:block;height:100%;background:linear-gradient(90deg,#2b9a68,#61bf92);border-radius:inherit}.card>footer{display:flex;align-items:center;justify-content:space-between;margin-top:14px}.card>footer>span{display:flex;align-items:center;gap:5px;color:var(--text-tertiary);font-size:9px}.card footer div{display:flex;gap:4px}.card footer button{display:grid;width:29px;height:29px;border:0;border-radius:6px;background:var(--bg-base);color:var(--text-tertiary);place-items:center}.loading i{height:210px;background:#edf1f5;border-radius:8px}.backdrop,.drawer-backdrop{position:fixed;z-index:100;inset:0;display:grid;padding:24px;background:rgba(28,39,56,.22);backdrop-filter:blur(10px);place-items:center}.editor{width:min(600px,100%);background:white;border-radius:10px;box-shadow:0 25px 70px rgba(28,42,62,.24)}.editor>header,aside>header{display:flex;align-items:center;justify-content:space-between;padding:20px;border-bottom:1px solid var(--border-subtle)}.editor h2,aside h2{margin:0;font-size:18px}.editor header p,aside header p{margin:3px 0 0;color:var(--text-tertiary);font-size:11px}.editor header button,aside header button{border:0;background:transparent;color:var(--text-tertiary)}.editor form{display:grid;grid-template-columns:repeat(2,1fr);gap:13px;padding:19px 20px 21px}.editor label{display:grid;gap:5px}.editor label span{font-size:11px;color:var(--text-secondary)}.editor input,.editor select{height:37px;padding:0 9px;border:1px solid var(--border-subtle);border-radius:7px}.editor .wide{grid-column:1/-1}.checkbox{display:flex!important;grid-template-columns:18px auto;align-items:center}.checkbox input{width:16px;height:16px}.editor footer{display:flex;justify-content:flex-end;gap:8px}.editor footer button{height:36px;padding:0 13px;border:1px solid var(--border-subtle);border-radius:7px;background:white}.editor footer .save{background:var(--accent);border-color:var(--accent);color:white}.drawer-backdrop{display:block;padding:0;background:rgba(31,42,58,.16)}aside{position:absolute;top:0;right:0;width:min(520px,60vw);min-width:430px;height:100%;overflow:auto;background:#fafcff;box-shadow:-18px 0 54px rgba(32,47,68,.16)}.history-row{display:grid;min-height:58px;grid-template-columns:8px minmax(0,1fr) 62px 116px;align-items:center;gap:10px;padding:0 20px;border-bottom:1px solid var(--border-subtle);font-size:10px}.history-row>i{width:7px;height:7px;border-radius:50%;background:#d0a13f}.history-row>i.operational{background:#2d9b6b}.history-row>i.failed,.history-row>i.error{background:#bc4d3c}.history-row>div{display:grid;gap:3px}.history-row span{color:var(--text-tertiary)}.history-row>strong{font-family:var(--font-data)}.empty{display:grid;min-height:240px;color:var(--text-tertiary);place-items:center}.spinning{animation:spin .75s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@keyframes enter{from{opacity:0;transform:translateY(6px)}}
@container app-content (max-width:850px){.monitor-page{padding:24px}.grid{grid-template-columns:1fr}.summary{grid-template-columns:1fr}.summary>div{border-right:0;border-bottom:1px solid var(--border-subtle)}.summary>div:last-child{border-bottom:0}}@container app-content (max-width:680px){.page-header{align-items:flex-start;flex-direction:column;gap:15px}.primary{width:100%;justify-content:center}.filters{flex-wrap:wrap}.filters label{flex:1}.editor form{grid-template-columns:1fr}.editor form>*{grid-column:1}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
.page-empty{margin-top:14px;background:white;border:1px solid var(--border-subtle);border-radius:8px}.page-empty>div{display:grid;justify-items:center;gap:7px}.page-empty strong{color:var(--text-primary);font-size:14px}.page-empty span{font-size:12px}.page-empty button{margin-top:5px;padding:7px 11px;border:0;border-radius:6px;background:var(--accent);color:white}
</style>
